package org.sleepwell.app;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;

/** Manual-only continuous capture with a separate bounded, ordered durable sink. */
final class SonarNight {
 interface Cues {default void event(long at,long duration,String category,double score){}default boolean masks(long fromNanos,long toNanos){return false;}default void pause(){}default void close(){}}
 static final Cues NO_CUES=new Cues(){};
 interface Clock extends SonarPump.Clock {long wall();}
 interface Sink extends AutoCloseable {
  default void periodicityBegin(long id,boolean enabled)throws Exception{if(enabled)throw new IllegalStateException("Periodic echo persistence unavailable");}
  default void periodicityWindow(long id,long from,long to,Double rate,double correlation,String quality)throws Exception{throw new IllegalStateException("Periodic echo persistence unavailable");}
  default void periodicityEnd(long id,boolean interrupted)throws Exception{}
  Session begin(SonarConfig config,String capture)throws Exception;
  default Session begin(SonarConfig config,String capture,boolean analysis)throws Exception{if(analysis)throw new IllegalStateException("Shared sound persistence unavailable");return begin(config,capture);}
  default void soundEvent(long id,long at,long duration,String category,double score)throws Exception{throw new IllegalStateException("Shared sound persistence unavailable");}
  default void soundStatus(long id,SoundAnalysisStatus status)throws Exception{if(status.requested)throw new IllegalStateException("Shared sound persistence unavailable");}
  default void clip(long id,SonarSoundClips.Clip clip)throws Exception{throw new IllegalStateException("Shared sound clip persistence unavailable");}
  void checkpoint(long id,long from,long to,Double movement,String quality,int samples,long active)throws Exception;
  void pause(long id,long at)throws Exception;void resume(long id,long at)throws Exception;
  void end(long id,long at,long active,boolean interrupted)throws Exception;default void end(long id,long at,long active,boolean interrupted,SoundAnalysisStatus analysis)throws Exception{if(analysis.requested)throw new IllegalStateException("Shared sound persistence unavailable");end(id,at,active,interrupted);}void close();
 }
 static final class Session {final long id,wall,elapsed;Session(long id,long wall,long elapsed){if(id<=0||wall<=0||elapsed<0)throw new IllegalArgumentException("Session anchor");this.id=id;this.wall=wall;this.elapsed=elapsed;}}
 static final class State {
  final String phase,message,error;final SoundAnalysisStatus analysis;final float gain;final long id,start,now,active;final boolean microphone;final List<SonarFrame> readings;
  State(float gain,String phase,String message,String error,long id,long start,long now,long active,boolean mic,List<SonarFrame> readings){this(gain,phase,message,error,id,start,now,active,mic,readings,SoundAnalysisStatus.initial(false));}
  State(float gain,String phase,String message,String error,long id,long start,long now,long active,boolean mic,List<SonarFrame> readings,SoundAnalysisStatus analysis){this.analysis=analysis;this.gain=gain;this.phase=phase;this.message=message;this.error=error;this.id=id;this.start=start;this.now=now;this.active=active;microphone=mic;this.readings=readings;}
 }
 private enum Desired {ACTIVE,PAUSE,STOP}
 private static final class Segment {final ArrayBlockingQueue<SonarObservation> queue=new ArrayBlockingQueue<>(512);final AtomicBoolean completed=new AtomicBoolean();volatile SonarRuntime runtime;volatile SonarEpochs epochs;volatile EchoPeriodicity periodicity;volatile SonarNightSound.Segment sound;volatile long start,base,cut=Long.MAX_VALUE;volatile boolean started,blocked;}
 private final boolean periodicity;private final Cues cues;private final SonarNightSound sounds;private final SonarConfig config;private final SonarRuntime.Factory audio;private final Sink sink;private final Clock clock;private final Executor ui;private final Consumer<State> listener;
 private final ScheduledThreadPoolExecutor storage=new ScheduledThreadPoolExecutor(1,r->new Thread(r,"SleepWell-sonar-storage"));
 private final AtomicLong revision=new AtomicLong();private final CountDownLatch closed=new CountDownLatch(1);private final ArrayDeque<SonarFrame> recent=new ArrayDeque<>();
 private volatile Segment segment;private volatile Session session;private volatile Desired desired=Desired.ACTIVE;private volatile String phase="IDLE",message="",error="",capture="";private volatile long accumulated;private volatile boolean interrupted,finished;private long lastPublished;
 SonarNight(SonarConfig config,SonarRuntime.Factory audio,Sink sink,Clock clock,Executor ui,Consumer<State> listener){this(config,audio,sink,clock,ui,listener,false,null);}
 SonarNight(SonarConfig config,SonarRuntime.Factory audio,Sink sink,Clock clock,Executor ui,Consumer<State> listener,boolean analysis,SoundAnalysisStream.Factory model){this(config,audio,sink,clock,ui,listener,analysis,model,SoundSensitivity.DEFAULT);}
 SonarNight(SonarConfig config,SonarRuntime.Factory audio,Sink sink,Clock clock,Executor ui,Consumer<State> listener,boolean analysis,SoundAnalysisStream.Factory model,SoundSensitivity sensitivity){this(config,audio,sink,clock,ui,listener,analysis,model,sensitivity,NO_CUES);}
 SonarNight(SonarConfig config,SonarRuntime.Factory audio,Sink sink,Clock clock,Executor ui,Consumer<State> listener,boolean analysis,SoundAnalysisStream.Factory model,SoundSensitivity sensitivity,Cues cues){this(config,audio,sink,clock,ui,listener,analysis,model,sensitivity,cues,false);}
 SonarNight(SonarConfig config,SonarRuntime.Factory audio,Sink sink,Clock clock,Executor ui,Consumer<State> listener,boolean analysis,SoundAnalysisStream.Factory model,SoundSensitivity sensitivity,Cues cues,boolean periodicity){this(config,audio,sink,clock,ui,listener,analysis,model,sensitivity,cues,periodicity,SonarClipPolicy.OFF);}
 SonarNight(SonarConfig config,SonarRuntime.Factory audio,Sink sink,Clock clock,Executor ui,Consumer<State> listener,boolean analysis,SoundAnalysisStream.Factory model,SoundSensitivity sensitivity,Cues cues,boolean periodicity,SonarClipPolicy clips){if(clips.requested&&!analysis)throw new IllegalArgumentException("Sound clips require explicit sound analysis consent");this.periodicity=periodicity;this.cues=java.util.Objects.requireNonNull(cues);this.sounds=new SonarNightSound(analysis,model,new SonarNightSound.Port(){public void event(long at,long duration,String category,double score)throws Exception{sink.soundEvent(session.id,at,duration,category,score);if(desired==Desired.ACTIVE&&!finished)cues.event(at,duration,category,score);}public void status(SoundAnalysisStatus status)throws Exception{sink.soundStatus(session.id,status);}public void clip(SonarSoundClips.Clip clip)throws Exception{sink.clip(session.id,clip);}},3600,sensitivity,clips);this.config=config;this.audio=audio;this.sink=sink;this.clock=clock;this.ui=ui;this.listener=listener;storage.setRemoveOnCancelPolicy(true);}
 synchronized void start(){if(!phase.equals("IDLE"))throw new IllegalStateException("Night already started");storage.scheduleWithFixedDelay(this::checkpoint,250,250,TimeUnit.MILLISECONDS);beginSegment();}
 synchronized boolean resume(){if(!phase.equals("PAUSED")||desired!=Desired.PAUSE||finished)return false;desired=Desired.ACTIVE;error="";beginSegment();return true;}
 synchronized void resumeFailed(String message){if(phase.equals("PAUSED")&&!finished){error=message;publish("PAUSED",message);}}
 private void beginSegment(){Segment owner=new Segment();segment=owner;owner.runtime=new SonarRuntime(audio,Runnable::run,state->runtimeState(owner,state),clock);publish("STARTING","Preparing contactless recording…");boolean accepted=owner.runtime.startNight(config,new SonarPump.NightSink(){
  public boolean periodicity(){return periodicity;}
  public void prepared(String actual)throws Exception{CompletableFuture<Void> ready=new CompletableFuture<>();storage.execute(()->{try{if(owner!=segment||desired!=Desired.ACTIVE)throw new InterruptedException();if(!Set.of("UNPROCESSED","VOICE_RECOGNITION").contains(actual))throw new IllegalStateException("Actual microphone source is unavailable.");if(session==null){capture=actual;session=sink.begin(config,actual,sounds.requested);sink.periodicityBegin(session.id,periodicity);owner.start=session.elapsed;}else{if(!capture.equals(actual))throw new IllegalStateException("Microphone source changed. Start a new contactless night.");owner.start=clock.millis();sink.resume(session.id,wall(owner.start));}owner.base=accumulated;Session pin=session;if(periodicity)owner.periodicity=new EchoPeriodicity(owner.start,(from,to,rate,correlation,quality)->sink.periodicityWindow(pin.id,wall(from),wall(to),rate,correlation,quality));owner.sound=sounds.begin(wall(owner.start),pin.wall,Math.multiplyExact(pin.elapsed,1000000L),storage);owner.epochs=new SonarEpochs(pin.wall,pin.elapsed,owner.start,owner.base,(from,to,value,quality,samples,active)->{sink.checkpoint(pin.id,from,to,value,quality,samples,active);sounds.captured(owner.sound,to,active);});ready.complete(null);}catch(Exception e){ready.completeExceptionally(e);}});try{ready.get();}catch(ExecutionException e){Throwable cause=e.getCause();if(cause instanceof Exception)throw (Exception)cause;throw new IllegalStateException(cause);}}
  public void started(){if(owner!=segment||desired!=Desired.ACTIVE){owner.runtime.cancel();return;}owner.started=true;publish("ACTIVE","Measuring contactless movement");}
  public void pcm(short[] pcm,int count,long firstNanos,boolean valid){if(owner!=segment||desired!=Desired.ACTIVE||owner.sound==null)return;owner.sound.worker.offer(pcm,count,firstNanos,valid&&!cues.masks(firstNanos,firstNanos+Math.round(count*1e9/SonarConfig.RATE))&&!DreamCues.masks(firstNanos,firstNanos+Math.round(count*1e9/SonarConfig.RATE)));}
  public void frame(SonarObservation observation){if(owner!=segment||desired!=Desired.ACTIVE)return;if(observation.to()>clock.millis()+40)throw new IllegalStateException("Capture timestamp is ahead of elapsed time.");if(cues.masks(observation.fromNanos,observation.toNanos)||DreamCues.masks(observation.fromNanos,observation.toNanos))observation=new SonarObservation(observation.fromNanos,observation.toNanos,new SonarFrame(observation.frame.from,observation.frame.to,null,SonarFrame.Quality.CUE_ACTIVE,observation.frame.snr,observation.frame.correlation));if(!owner.queue.offer(observation))throw new IllegalStateException("Contactless storage could not keep up. Recording stopped.");Session pin=session;long relative=observation.from()-pin.elapsed;if(relative<0)throw new IllegalStateException("Capture predates the session anchor.");SonarFrame point=new SonarFrame(relative,relative+40,observation.frame.movement,observation.frame.quality,observation.frame.snr,observation.frame.correlation);synchronized(recent){recent.addLast(point);while(recent.size()>375)recent.removeFirst();}long now=clock.millis();if(now-lastPublished>=200){lastPublished=now;publish("ACTIVE",SonarRuntime.copy(observation.frame));}}
 });if(!accepted){error="Audio is still owned by a previous test or recording. Wait for cleanup or restart SleepWell.";interrupted=true;desired=Desired.STOP;owner.cut=clock.millis();complete(owner,SonarFrame.Quality.UNAVAILABLE);}}
 private synchronized void runtimeState(Segment owner,SonarRuntime.State state){if(owner!=segment||state.busy)return;owner.started=state.phase.equals("BLOCKED");owner.blocked=state.phase.equals("BLOCKED");if(state.phase.equals("ERROR")||owner.blocked){cues.close();error=state.message;interrupted=true;desired=Desired.STOP;}else if(desired==Desired.ACTIVE)desired=Desired.STOP;if(owner.cut==Long.MAX_VALUE)owner.cut=clock.millis();complete(owner,state.failure==null?SonarFrame.Quality.UNAVAILABLE:state.failure);}
 private void complete(Segment owner,SonarFrame.Quality missing){if(!owner.completed.compareAndSet(false,true))return;storage.execute(()->{
  try{if(owner.epochs!=null){owner.cut=Math.max(owner.start,owner.cut);accumulated=owner.base+Math.max(0,owner.cut-owner.start);}drain(owner,owner.cut);if(owner.epochs!=null)owner.epochs.finish(owner.cut,missing);}
  catch(Exception failure){failStorage(failure,owner);}
  finally{if(!finished)try{sounds.finish(owner.sound,Math.multiplyExact(owner.cut,1000000L),()->{try{finishSegment(owner);}catch(Exception failure){failStorage(failure,owner);}},failure->failStorage(failure,owner));}catch(Exception failure){failStorage(failure,owner);}}
 });}
 private void finishSegment(Segment owner)throws Exception{if(desired==Desired.PAUSE&&!owner.blocked&&session!=null){sink.pause(session.id,wall(owner.cut));publish("PAUSED","Speaker and microphone stopped");return;}finishStorage(owner.blocked);}
 private void checkpoint(){if(finished)return;Segment owner=segment;if(owner==null||owner.epochs==null)return;try{long end=Math.min(owner.cut,clock.millis());drain(owner,end);sounds.flush(owner.sound);if(desired==Desired.ACTIVE){owner.epochs.through(Math.max(owner.start,end-1000),owner.started?SonarFrame.Quality.UNAVAILABLE:SonarFrame.Quality.CALIBRATING);if(session!=null&&clock.millis()-session.elapsed>=12*3600000L)stop(false);}}catch(Exception failure){failStorage(failure,owner);}}
 private void drain(Segment owner,long through)throws Exception{for(int n=0;n<512;n++){SonarObservation frame=owner.queue.peek();if(frame==null||frame.to()>through)break;owner.queue.remove();owner.epochs.add(frame,through);if(owner.periodicity!=null)owner.periodicity.add(frame);}}
 private void failStorage(Exception failure,Segment owner){cues.close();sounds.storageFailed();synchronized(this){error="Could not save contactless readings: "+(failure.getMessage()==null?"storage unavailable":failure.getMessage());interrupted=true;desired=Desired.STOP;if(owner.cut==Long.MAX_VALUE)owner.cut=clock.millis();if(owner.epochs!=null)accumulated=owner.base+Math.max(0,owner.cut-owner.start);}if(owner.runtime!=null)owner.runtime.cancel();if(owner.completed.get()&&(owner.sound==null||owner.sound.closed))try{finishStorage(owner.blocked);}catch(Exception ending){error+="; finalization failed: "+ending.getMessage();try{sink.close();}finally{finished=true;publish(owner.blocked?"BLOCKED":"CLOSED",error);storage.shutdown();closed.countDown();}}}
 synchronized void pause(){if(desired!=Desired.ACTIVE||!phase.equals("ACTIVE")&&!phase.equals("STARTING"))return;desired=Desired.PAUSE;cues.pause();Segment owner=segment;owner.cut=clock.millis();publish("PAUSING","Stopping speaker and microphone…");owner.runtime.cancel();}
 synchronized void stop(boolean wasInterrupted){cues.close();interrupted|=wasInterrupted;if(finished||phase.equals("STOPPING")||phase.equals("BLOCKED"))return;boolean wasPaused=phase.equals("PAUSED");desired=Desired.STOP;Segment owner=segment;if(owner==null){storage.execute(()->{try{finishStorage(false);}catch(Exception failure){error=failure.getMessage();publish("CLOSED",error);closed.countDown();}});return;}if(owner.cut==Long.MAX_VALUE||wasPaused)owner.cut=clock.millis();publish("STOPPING","Saving contactless recording…");if(owner.completed.get()&&(owner.sound==null||owner.sound.closed))storage.execute(()->{try{finishStorage(owner.blocked);}catch(Exception failure){failStorage(failure,owner);}});else owner.runtime.cancel();}
 private void finishStorage(boolean blocked){if(finished)return;cues.close();try{if(session!=null){long ended=segment==null?clock.millis():Math.max(session.elapsed,segment.cut);sink.periodicityEnd(session.id,interrupted||blocked);sink.end(session.id,wall(ended),accumulated,interrupted||blocked,sounds.ended(interrupted||blocked));}}catch(Exception failure){interrupted=true;error=(error.isEmpty()?"":error+" ")+"Could not finalize the contactless night: "+failure.getMessage();}finally{try{sink.close();}catch(RuntimeException failure){error=(error.isEmpty()?"":error+" ")+"Could not close recording storage: "+failure.getMessage();}finally{finished=true;try{publish(blocked?"BLOCKED":"CLOSED",error.isEmpty()?(session==null?"Contactless start cancelled. No night was recorded.":"Contactless recording saved"):error);}finally{storage.shutdown();closed.countDown();}}}}
 private long wall(long elapsed){Session pin=session;return pin==null?clock.wall():Math.addExact(pin.wall,elapsed-pin.elapsed);}
 State state(){Session pin=session;Segment owner=segment;long active=accumulated;if(owner!=null&&owner.epochs!=null&&!owner.completed.get())active=owner.base+Math.max(0,Math.min(clock.millis(),owner.cut)-owner.start);List<SonarFrame> frames;synchronized(recent){frames=List.copyOf(recent);}return new State(config.gain,phase,message,error,pin==null?0:pin.id,pin==null?clock.wall():pin.wall,pin==null?clock.wall():wall(clock.millis()),active,owner!=null&&owner.started,frames,finished?sounds.ended(interrupted||owner!=null&&owner.blocked):sounds.state());}
 private synchronized void publish(String next,String copy){if((next.equals("ACTIVE")||next.equals("STARTING"))&&desired!=Desired.ACTIVE||next.equals("PAUSED")&&desired!=Desired.PAUSE)return;phase=next;message=copy;long version=revision.incrementAndGet();State value=state();ui.execute(()->{if(revision.get()==version)listener.accept(value);});}
 boolean awaitClosed(long timeout)throws InterruptedException{return closed.await(timeout,TimeUnit.MILLISECONDS);}
}
